using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;
using Microsoft.CodeAnalysis.Text;
using Slopwatch.Detection;

namespace Slopwatch.Analysis;

/// <summary>
/// Detects generated code using the same conventions Roslyn's own analyzers use.
/// </summary>
/// <remarks>
/// Mirrors <c>Roslyn.Utilities.GeneratedCodeUtilities</c> so that slopwatch skips the
/// same files the compiler and built-in analyzers skip. Three signals are recognized:
/// <list type="number">
/// <item><description>A generated filename (<c>TemporaryGeneratedFile_*</c>, <c>*.designer</c>,
/// <c>*.generated</c>, <c>*.g</c>, <c>*.g.i</c>).</description></item>
/// <item><description>An <c>&lt;auto-generated&gt;</c> marker inside a leading comment.</description></item>
/// <item><description>A <c>[GeneratedCode]</c> or <c>[DebuggerNonUserCode]</c> attribute on the
/// enclosing type declaration.</description></item>
/// </list>
/// <para>
/// Known deviations from Roslyn, both in the conservative direction (a file is analyzed rather
/// than skipped): a <c>partial</c> type is never treated as generated, because the attribute may
/// live on a declaration in another file and resolving that requires a compilation; and an
/// attribute referenced through a <c>using</c> alias is not recognized for the same reason.
/// </para>
/// </remarks>
public static class GeneratedCodeDetector
{
    /// <summary>
    /// Markers Roslyn looks for inside leading comment trivia. Matching is ordinal
    /// (case-sensitive), as in Roslyn.
    /// </summary>
    private static readonly string[] AutoGeneratedMarkers = { "<autogenerated", "<auto-generated" };

    /// <summary>
    /// Filename suffixes (applied to the name without its extension) that identify generated files.
    /// </summary>
    private static readonly string[] GeneratedFileNameSuffixes = { ".designer", ".generated", ".g", ".g.i" };

    /// <summary>
    /// Prefix used by Roslyn for its temporary generated files.
    /// </summary>
    private const string TemporaryGeneratedFilePrefix = "TemporaryGeneratedFile_";

    /// <summary>
    /// Unqualified attribute names that mark a type as generated.
    /// </summary>
    private static readonly string[] SimpleGeneratedCodeAttributeNames =
    {
        "GeneratedCode",
        "GeneratedCodeAttribute",
        "DebuggerNonUserCode",
        "DebuggerNonUserCodeAttribute"
    };

    /// <summary>
    /// Fully qualified attribute names that mark a type as generated.
    /// </summary>
    /// <remarks>
    /// A qualified name is only accepted when it matches one of these exactly. An attribute in a
    /// different namespace that happens to be called <c>GeneratedCode</c> is a different attribute
    /// and must not cause a skip.
    /// </remarks>
    private static readonly string[] QualifiedGeneratedCodeAttributeNames =
    {
        "System.CodeDom.Compiler.GeneratedCode",
        "System.CodeDom.Compiler.GeneratedCodeAttribute",
        "System.Diagnostics.DebuggerNonUserCode",
        "System.Diagnostics.DebuggerNonUserCodeAttribute"
    };

    /// <summary>
    /// Number of leading lines scanned when no syntax tree is available.
    /// </summary>
    private const int FallbackScanLineLimit = 10;

    /// <summary>
    /// Determines whether a file is generated based on its name alone.
    /// </summary>
    /// <param name="filePath">The path to the file.</param>
    /// <returns>True if the filename matches a known generated-code convention.</returns>
    public static bool IsGeneratedFile(string filePath)
    {
        var fileName = Path.GetFileName(filePath);

        if (fileName.StartsWith(TemporaryGeneratedFilePrefix, StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        var extension = Path.GetExtension(fileName);
        if (string.IsNullOrEmpty(extension))
        {
            return false;
        }

        var fileNameWithoutExtension = Path.GetFileNameWithoutExtension(fileName);
        foreach (var suffix in GeneratedFileNameSuffixes)
        {
            if (fileNameWithoutExtension.EndsWith(suffix, StringComparison.OrdinalIgnoreCase))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Determines whether a file is generated based on its name and content.
    /// </summary>
    /// <param name="filePath">The path to the file.</param>
    /// <param name="content">The file content.</param>
    /// <param name="syntaxTree">
    /// The parsed syntax tree, when available. Used to inspect leading comment trivia the way
    /// Roslyn does; falls back to a text scan when the file could not be parsed.
    /// </param>
    /// <returns>True if the file declares itself generated.</returns>
    public static bool IsGeneratedFile(string filePath, string content, SyntaxTree? syntaxTree)
    {
        return IsGeneratedFile(filePath) || BeginsWithAutoGeneratedComment(filePath, content, syntaxTree);
    }

    /// <summary>
    /// Determines whether a syntax node belongs to a type marked with a generated-code attribute.
    /// </summary>
    /// <param name="node">The node to inspect.</param>
    /// <returns>True if an enclosing type declaration carries a generated-code attribute.</returns>
    /// <remarks>
    /// Roslyn treats a partial type with more than one declaration as non-generated, because the
    /// attribute may live on a different declaration. Without a compilation we cannot resolve that,
    /// so partial types are conservatively treated as hand-written.
    /// </remarks>
    public static bool HasGeneratedCodeAttribute(SyntaxNode node)
    {
        foreach (var ancestor in node.AncestorsAndSelf())
        {
            if (ancestor is not BaseTypeDeclarationSyntax typeDeclaration)
            {
                continue;
            }

            if (typeDeclaration.Modifiers.Any(SyntaxKind.PartialKeyword))
            {
                continue;
            }

            foreach (var attributeList in typeDeclaration.AttributeLists)
            {
                foreach (var attribute in attributeList.Attributes)
                {
                    if (IsGeneratedCodeAttributeName(attribute.Name))
                    {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    /// <summary>
    /// Determines whether a detection result falls inside a generated type declaration.
    /// </summary>
    /// <param name="result">The detection result.</param>
    /// <param name="syntaxTree">The syntax tree the result was produced from.</param>
    /// <returns>True if the result's position is inside a generated type.</returns>
    /// <remarks>
    /// The lookup uses both the line and the column. Using the line start alone would resolve to
    /// whatever node begins that line, which can be an unrelated type on a shared line.
    /// </remarks>
    public static bool IsResultInGeneratedType(DetectionResult result, SyntaxTree? syntaxTree)
    {
        if (syntaxTree is null)
        {
            return false;
        }

        var text = syntaxTree.GetText();
        var lineIndex = result.LineNumber - 1;

        if (lineIndex < 0 || lineIndex >= text.Lines.Count)
        {
            return false;
        }

        var line = text.Lines[lineIndex];
        var columnOffset = Math.Max(0, result.Column - 1);
        var position = Math.Min(line.Start + columnOffset, line.End);

        // A one-character span resolves to the token at the reported position. A zero-width span
        // can bind to the node that ends there instead.
        var spanLength = Math.Min(1, line.End - position);
        var node = syntaxTree.GetRoot().FindNode(new TextSpan(position, spanLength), getInnermostNodeForTie: true);

        return HasGeneratedCodeAttribute(node);
    }

    /// <summary>
    /// Checks leading comment trivia for an auto-generated marker.
    /// </summary>
    private static bool BeginsWithAutoGeneratedComment(string filePath, string content, SyntaxTree? syntaxTree)
    {
        if (syntaxTree is not null)
        {
            foreach (var trivia in syntaxTree.GetRoot().GetLeadingTrivia())
            {
                if (!IsCommentTrivia(trivia))
                {
                    continue;
                }

                if (ContainsAutoGeneratedMarker(trivia.ToString()))
                {
                    return true;
                }
            }

            return false;
        }

        // No syntax tree. Razor markup is scanned differently: a line that merely starts with
        // "//" may be markup text (for example inside <pre>) rather than a comment, so only
        // Razor comment blocks count.
        return IsRazorFile(filePath)
            ? RazorCommentContainsMarker(content)
            : CSharpTextContainsMarker(content);
    }

    /// <summary>
    /// Scans the first few lines of C# source for a comment carrying the marker.
    /// </summary>
    private static bool CSharpTextContainsMarker(string content)
    {
        var lines = content.Split('\n');
        var limit = Math.Min(lines.Length, FallbackScanLineLimit);

        for (var i = 0; i < limit; i++)
        {
            var line = lines[i].Trim();

            if (!line.StartsWith("//", StringComparison.Ordinal) &&
                !line.StartsWith("/*", StringComparison.Ordinal) &&
                !line.StartsWith("*", StringComparison.Ordinal))
            {
                continue;
            }

            if (ContainsAutoGeneratedMarker(line))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Scans Razor comment blocks (<c>@* ... *@</c>) for the marker.
    /// </summary>
    private static bool RazorCommentContainsMarker(string content)
    {
        var searchLimit = Math.Min(content.Length, FallbackScanLineLimit * 200);
        var index = 0;

        while (index < searchLimit)
        {
            var open = content.IndexOf("@*", index, StringComparison.Ordinal);
            if (open < 0 || open >= searchLimit)
            {
                return false;
            }

            var close = content.IndexOf("*@", open + 2, StringComparison.Ordinal);
            if (close < 0)
            {
                return false;
            }

            if (ContainsAutoGeneratedMarker(content.Substring(open + 2, close - open - 2)))
            {
                return true;
            }

            index = close + 2;
        }

        return false;
    }

    private static bool IsRazorFile(string filePath)
    {
        return filePath.EndsWith(".razor", StringComparison.OrdinalIgnoreCase)
            || filePath.EndsWith(".cshtml", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsCommentTrivia(SyntaxTrivia trivia)
    {
        return trivia.IsKind(SyntaxKind.SingleLineCommentTrivia)
            || trivia.IsKind(SyntaxKind.MultiLineCommentTrivia)
            || trivia.IsKind(SyntaxKind.SingleLineDocumentationCommentTrivia)
            || trivia.IsKind(SyntaxKind.MultiLineDocumentationCommentTrivia);
    }

    private static bool ContainsAutoGeneratedMarker(string text)
    {
        foreach (var marker in AutoGeneratedMarkers)
        {
            if (text.Contains(marker, StringComparison.Ordinal))
            {
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// Matches an attribute name against the known generated-code attributes.
    /// </summary>
    /// <remarks>
    /// An unqualified name is accepted on its simple name. A qualified name must match one of the
    /// fully qualified names exactly, so an unrelated attribute such as <c>Acme.GeneratedCode</c>
    /// does not qualify.
    /// </remarks>
    private static bool IsGeneratedCodeAttributeName(NameSyntax name)
    {
        if (name is SimpleNameSyntax simple)
        {
            foreach (var attributeName in SimpleGeneratedCodeAttributeNames)
            {
                if (string.Equals(simple.Identifier.ValueText, attributeName, StringComparison.Ordinal))
                {
                    return true;
                }
            }

            return false;
        }

        var qualified = name.ToString();
        const string globalPrefix = "global::";
        if (qualified.StartsWith(globalPrefix, StringComparison.Ordinal))
        {
            qualified = qualified.Substring(globalPrefix.Length);
        }

        foreach (var attributeName in QualifiedGeneratedCodeAttributeNames)
        {
            if (string.Equals(qualified, attributeName, StringComparison.Ordinal))
            {
                return true;
            }
        }

        return false;
    }
}
